-- PT112-S1-Q4. Batch 07.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch07$PT112-S1-Q4$batch07$ AND q.stimulus=$batch07$Most antidepressant drugs cause weight gain. While dieting can help reduce the amount of weight gained while taking such antidepressants, some weight gain is unlikely to be preventable.$batch07$ AND q.prompt=$batch07$The information above most strongly supports which one of the following?$batch07$ AND q.correct_choice=$batch07$C$batch07$) THEN RAISE EXCEPTION 'Question changed: PT112-S1-Q4'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch07$PT112-S1-Q4$batch07$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT112-S1-Q4'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch07$PT112-S1-Q4$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch07$Statements$batch07$, $batch07$Most antidepressants cause weight gain. Dieting can reduce the weight gained, but some of the gain probably can't be prevented.$batch07$), (1, $batch07$Evaluate$batch07$, $batch07$Pause and infer. If the drugs cause weight gain and some of it can't be prevented, then some patients will gain weight because of the drugs. The claim is small, and that is what makes it safe.$batch07$), (2, $batch07$Goal$batch07$, $batch07$At least some patients gain weight from the drugs.$batch07$)) v(position,label,body) WHERE q.qid=$batch07$PT112-S1-Q4$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch07$A$batch07$, $batch07$The passage gives no rule about what doctors should prescribe.$batch07$), ($batch07$B$batch07$, $batch07$Again, no advice about who should ask for antidepressants.$batch07$), ($batch07$C$batch07$, $batch07$The drugs cause weight gain, and some of it "is unlikely to be preventable". "At least some" asks for very little, and the passage gives more than enough.$batch07$), ($batch07$D$batch07$, $batch07$The passage says some gain probably can't be prevented even with dieting. So the gain isn't simply due to not dieting.$batch07$), ($batch07$E$batch07$, $batch07$"All patients should diet" is a recommendation the passage never makes.$batch07$)) v(letter,body) WHERE q.qid=$batch07$PT112-S1-Q4$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
